            <TimelineBlocks blocks={timeline(historyAfter(message.id), changesAfter(message.id))} restorePoints={restorePoints} onRevert={onRevert}
              onDiscussFailure={discussFailure} discussDisabled={streamingMessageId !== null} />
          </Fragment>
        );
      })}
    </div>
  );
}
