import { BuildInfo, ExportedCopyInfo, PhysicalPrintInfo, SliceStatisticsInfo } from '../bridge/protocol';
import { chatTimestamp } from './ChatNavigation';

export type ManufacturingHistoryEntry =
  | { kind: 'build'; seq: number; afterMessageId: string; record: BuildInfo; copy?: ExportedCopyInfo }
  | { kind: 'copy'; seq: number; afterMessageId: string; record: ExportedCopyInfo }
  | { kind: 'print'; seq: number; afterMessageId: string; record: PhysicalPrintInfo };

function decimal(value: number, digits: number): string {
  return new Intl.NumberFormat(undefined, { maximumFractionDigits: digits }).format(value);
}

// The resting line reads the print time the way a person says it ("2h 36m");
// the exact minute count stays in the statistics list behind the disclosure.
function coarseDuration(seconds: number): string {
  const minutes = Math.round(seconds / 60);
  const hours = Math.floor(minutes / 60);
  return hours > 0 ? `${hours}h ${String(minutes % 60).padStart(2, '0')}m` : `${minutes}m`;
}

// The leading eight hex digits in the two groups the timeline reads them as.
// The <code> keeps the whole digest in its title, as the expanded rows do.
function shortHash(hash: string): string {
  return `${hash.slice(0, 4)} ${hash.slice(4, 8)}`;
}

function summaryStats(statistics: SliceStatisticsInfo): string {
  return `${coarseDuration(statistics.printTimeSeconds)} · ${decimal(statistics.materialGrams, 1)} g · ${statistics.layerCount} layers`;
}

function HashValue({ label, value }: { label: string; value: string }) {
  return (
    <div className="history-hash">
      <dt>{label}</dt>
      <dd><code title={value}>{value}</code></dd>
    </div>
  );
}

function Statistics({ statistics }: { statistics: SliceStatisticsInfo }) {
  const duration = decimal(statistics.printTimeSeconds / 60, 0);
  const filament = decimal(statistics.filamentMm, 1);
  const grams = decimal(statistics.materialGrams, 1);
  const cost = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' }).format(statistics.materialCost);
  return (
    <dl className="history-stats" aria-label="Slice statistics">
      <div><dt>Time</dt><dd>{duration} min</dd></div>
      <div><dt>Filament</dt><dd>{filament} mm</dd></div>
      <div><dt>Material</dt><dd>{grams} g · {cost}</dd></div>
      <div><dt>Layers</dt><dd>{statistics.layerCount}</dd></div>
    </dl>
  );
}

function Facts({ plate, printer, material }: { plate: string; printer: string; material: string }) {
  return (
    <dl className="history-facts">
      <div><dt>Plate</dt><dd>{plate || 'Unnamed plate'}</dd></div>
      <div><dt>Printer</dt><dd>{printer || 'Not recorded'}</dd></div>
      <div><dt>Material</dt><dd>{material || 'Not recorded'}</dd></div>
    </dl>
  );
}

// The card rests as this summary. Everything the record carries stays mounted
// in the sibling detail, which the disclosure reveals on demand rather than
// re-rendering: product-definition.md §2.7 puts the full change history under
// "what should appear when expanded".
function HistorySummary({ kind, id, status, tone, time, children }: {
  kind: string;
  id: string;
  status: string;
  tone: string;
  time: string;
  children?: ReactNode;
}) {
  return (
    <summary className="history-summary">
      <span className="history-summary-head">
        <span className="history-title"><span className="history-kind">{kind}</span><strong>{id}</strong></span>
        <span className={`history-status ${tone}`}>{status}</span>
        {time && <span className="history-time">{time}</span>}
        <span className="history-disclosure" aria-hidden="true" />
      </span>
      {children}
    </summary>
  );
}

export function ManufacturingHistoryCard({ entry, onDiscussFailure, discussDisabled = false }: {
  entry: ManufacturingHistoryEntry;
  onDiscussFailure?: (print: PhysicalPrintInfo) => void;
  discussDisabled?: boolean;
}) {
  if (entry.kind === 'build') {
    const build = entry.record;
    const copy = entry.copy;
    const copyName = copy?.destination.split(/[\\/]/).pop();
    return (
      <article className="history-card build-card" aria-label={`Build ${build.id}`}>
        <details className="history-details">
          <summary className="history-summary">
            <span className="history-summary-head">
              <span className="history-title"><span className="history-kind">G-code</span>
                <code title={build.outputHash}>{build.outputHash ? shortHash(build.outputHash) : build.id}</code></span>
              <span className="history-time">{chatTimestamp(build.createdAt)}</span>
              <span className="history-disclosure" aria-hidden="true" />
            </span>
            <strong className="build-stats-line">{summaryStats(build.statistics)}</strong>
            {build.printer && <span className="build-target">{build.sentAt ? 'Sent to' : 'Sliced for'} {build.printer}</span>}
            {build.deliveryConfirmedAt && <span className="build-delivery">✓ {chatTimestamp(build.deliveryConfirmedAt)} · on {build.deliveryLocation || 'the printer'}</span>}
            {copy && <span className="build-export">{copyName || copy.destination} · {copy.verified ? 'Checksum verified' : copy.modified ? 'Checksum differs' : 'Not checked'}</span>}
            {(build.sentAt || copy?.verified) && <span className="history-reprint" aria-disabled="true"
              title="This build does not retain a G-code file that the app can resend">Reprint this G-code</span>}
          </summary>
          <div className="history-detail">
            {build.stale && <p className="history-note">Stale · The project changed after this G-code was made. Slice again to match the plate.</p>}
            <Facts plate={build.plateName} printer={build.printer} material={build.material} />
            <Statistics statistics={build.statistics} />
            <dl className="history-hashes">
              <HashValue label="Input SHA-256" value={build.manufacturingInputHash} />
              <HashValue label="G-code SHA-256" value={build.outputHash} />
            </dl>
            <p className="history-provenance">{build.slicerVersion} · {build.configurationProvenance}</p>
            {build.warnings.length > 0 && <ul className="history-warnings">{build.warnings.map((warning, index) => <li key={index}>{warning}</li>)}</ul>}
          </div>
        </details>
      </article>
    );
  }

  if (entry.kind === 'copy') {
    const copy = entry.record;
    const status = copy.modified ? 'Checksum differs' : copy.verified ? 'Checksum verified' : 'Not checked';
    return (
      <article className="history-card copy-card" aria-label={`Exported copy ${copy.id}`}>
        <details className="history-details">
          <HistorySummary
            kind="Exported copy"
            id={copy.id}
            status={status}
            tone={copy.modified ? 'warning' : copy.verified ? 'success' : ''}
            time={chatTimestamp(copy.createdAt)}
          >
            {copy.destination && <span className="history-line long-content">{copy.destination}</span>}
          </HistorySummary>
          <div className="history-detail">
            <dl className="history-facts">
              <div><dt>Build</dt><dd>{copy.buildId}</dd></div>
              <div><dt>Destination</dt><dd className="long-content">{copy.destination}</dd></div>
            </dl>
            <dl className="history-hashes"><HashValue label="Expected SHA-256" value={copy.expectedOutputHash} /></dl>
          </div>
        </details>
      </article>
    );
  }

  const print = entry.record;
  const started = chatTimestamp(print.startedAt);
  const ended = chatTimestamp(print.endedAt);
  const runWindow = started && ended ? `${started} → ${ended}` : started || ended;
  const elapsedSeconds = (Date.parse(print.endedAt) - Date.parse(print.startedAt)) / 1000;
  const elapsed = Number.isFinite(elapsedSeconds) && elapsedSeconds >= 0 ? coarseDuration(elapsedSeconds) : '';
  const details = (
    <div className="history-detail">
      <Facts plate={print.plateName} printer={print.printer} material={print.material} />
      <dl className="history-facts">
        <div><dt>Started</dt><dd>{print.startedAt}</dd></div>
        <div><dt>Ended</dt><dd>{print.endedAt}</dd></div>
        {print.failure && <div><dt>Failure</dt><dd>{print.failure}</dd></div>}
      </dl>
      <Statistics statistics={print.statistics} />
      <dl className="history-hashes">
        <HashValue label="Input SHA-256" value={print.manufacturingInputHash} />
        <HashValue label="Build SHA-256" value={print.outputHash} />
        <HashValue label="Printed G-code SHA-256" value={print.gcodeHash} />
      </dl>
    </div>
  );
  if (print.outcome === 'failed') {
    return (
      <article className="history-card print-card print-failed" aria-label={`Failed physical print ${print.id}`}>
        <details className="history-details">
          <summary className="history-summary">
            <span className="failure-heading">
              <span className="failure-kicker"><span className="failure-dot" aria-hidden="true" />Print failed</span>
              {runWindow && <span className="failure-time">{runWindow}</span>}
              <span className="history-disclosure" aria-hidden="true" />
            </span>
            <strong className="failure-title">{print.printer || 'Printer'} · stopped{print.stoppedPercent !== undefined ? ` at ${print.stoppedPercent}%${elapsed ? `, ${elapsed} in` : ''}` : elapsed ? ` after ${elapsed}` : ''}</strong>
            {print.failure && <span className="failure-reason">{print.failure}{print.gcodeHash && ` · G-code ${shortHash(print.gcodeHash)}`}</span>}
          </summary>
          {details}
        </details>
        {onDiscussFailure && <button type="button" className="failure-action" disabled={discussDisabled}
          onClick={() => onDiscussFailure(print)}>Discuss this failure</button>}
      </article>
    );
  }
  return (
    <article className="history-card print-card" aria-label={`Physical print ${print.id}`}>
      <details className="history-details">
        <HistorySummary
          kind="Physical print"
          id={print.id}
          status={print.outcome}
          tone={print.outcome === 'completed' ? 'success' : 'warning'}
          time={runWindow}
        >
          {print.printer && <span className="history-line">{print.printer}</span>}
          {print.failure && <span className="history-line history-note">{print.failure}</span>}
        </HistorySummary>
        {details}
      </details>
    </article>
  );
}
"}

{"i":2,"result":"// The change log between the turns: what the person and the Agent changed,
// drawn as the Figma "Hand edits" frame has it -- one row per run of the same
// edit, hairlines above and below the group, no bubble. The
// native side records every edit raw; merging and wording happen here only,
// so either can change without touching saved data.

import { ReactNode, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { ChangeInfo, RestorePointInfo } from '../bridge/protocol';
import { chatTimestamp } from './ChatNavigation';

export interface ChangeRun {
  first: ChangeInfo;
  last: ChangeInfo;
  count: number;
}

// Consecutive entries merge when they are the same edit by the same actor:
// the same kind and label, which for a setting is the same setting. Eleven
// rotate steps are one row; a rotate then a move are two.
export function groupChanges(changes: ChangeInfo[]): ChangeRun[] {
  const runs: ChangeRun[] = [];
  for (const change of [...changes].sort((a, b) => a.seq - b.seq)) {
    const run = runs[runs.length - 1];
    if (run && run.last.kind === change.kind && run.last.label === change.label && run.last.actor === change.actor) {
      run.last = change;
      run.count += 1;
    } else {
      runs.push({ first: change, last: change, count: 1 });
    }
  }
  return runs;
}

// OrcaSlicer's own step names where they read as code rather than as what the
// person did. Everything else is shown as OrcaSlicer names it.
const STEP_NAMES: Record<string, string> = {
  'select_arrange partplate': 'Arrange plate',
  smooth_mesh: 'Smooth mesh',
  MoveInMeasure: 'Move',
};

// Seven real edits take an undo step with no name at all: deleting instances
// or parts, adding or editing layer ranges, and the printable and auto-drop
// toggles.
const UNNAMED_STEP = 'Object settings changed';

function stepName(label: string): string {
  return label === '' ? UNNAMED_STEP : STEP_NAMES[label] ?? label;
}

function title(run: ChangeRun): ReactNode {
  const { first, last } = run;
  switch (last.kind) {
    case 'step':
      return stepName(last.label);
    case 'undo':
      return `Undo: ${stepName(last.label)}`;
    case 'redo':
      return `Redo: ${stepName(last.label)}`;
    case 'setting':
      // A run of edits to one setting reads as its net change.
      return (
        <>
          {last.label} {first.from || 'none'} → <strong>{last.to || 'none'}</strong>
        </>
      );
    case 'preset':
      return (
        <>
          Switched to <strong>{last.label}</strong>
        </>
      );
    case 'restore':
      return last.label;
  }
}

function meta(run: ChangeRun): string {
  const who = run.last.actor === 'agent' ? 'Agent' : 'you';
  const context = run.last.kind === 'setting' && run.last.preset ? `in ${run.last.preset}` : run.last.location;
  const parts = [context ? `${who}, ${context}` : who];
  if (run.count > 1) parts.push(`${run.count} steps merged`);
  const time = chatTimestamp(run.last.createdAt);
  if (time) parts.push(time);
  return parts.join(' · ');
}

export function ChangeRows({ changes, restorePoints = [], onRevert }: {
  changes: ChangeInfo[];
  restorePoints?: RestorePointInfo[];
  onRevert?: (versionId: string) => void;
}) {
  const [open, setOpen] = useState<string | null>(null);
  const [settingsExpanded, setSettingsExpanded] = useState(false);
  const [summaryExpanded, setSummaryExpanded] = useState(false);
  const [position, setPosition] = useState({ top: 0, left: 0 });
  const anchor = useRef<HTMLButtonElement | null>(null);
  const popover = useRef<HTMLDivElement | null>(null);
  const cancel = useRef<HTMLButtonElement | null>(null);
  const points = new Map(restorePoints.map((point) => [point.changeSeq, point.versionId]));
  const runs = groupChanges(changes);
  const isAgentSetting = (run: ChangeRun) =>
    run.last.kind === 'setting' && run.last.actor === 'agent' && !points.has(run.last.seq);

  useLayoutEffect(() => {
    if (!open || !anchor.current || !popover.current) return;
    const update = () => {
      const button = anchor.current!.getBoundingClientRect();
      const panel = popover.current!;
      const left = Math.max(12, Math.min(button.right - panel.offsetWidth, window.innerWidth - panel.offsetWidth - 12));
      const above = button.top - panel.offsetHeight - 4;
      const top = above >= 12 ? above
        : Math.min(button.bottom + 4, window.innerHeight - panel.offsetHeight - 12);
      setPosition({ top, left });
    };
    update();
    window.addEventListener('scroll', update, true);
    window.addEventListener('resize', update);
    return () => {
      window.removeEventListener('scroll', update, true);
      window.removeEventListener('resize', update);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;
    cancel.current?.focus();
    const dismiss = (event: MouseEvent) => {
      if (!popover.current?.contains(event.target as Node) && !anchor.current?.contains(event.target as Node))
        setOpen(null);
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { setOpen(null); anchor.current?.focus(); }
    };
    document.addEventListener('pointerdown', dismiss);
    document.addEventListener('keydown', escape);
    return () => {
      document.removeEventListener('pointerdown', dismiss);
      document.removeEventListener('keydown', escape);
    };
  }, [open]);

  const entries: ReactNode[] = [];
  for (let index = 0; index < runs.length;) {
    const step = runs[index];
    if (step.last.kind === 'step' && step.last.actor === 'agent') {
      let end = index + 1;
      while (end < runs.length && isAgentSetting(runs[end])) end += 1;
      const settings = runs.slice(index + 1, end);
      if (settings.length >= 2) {
        const value = (label: string) => settings.find((run) => run.last.label === label)?.last.to;
        const walls = value('Wall loops');
        const density = value('Sparse infill density');
        const pattern = value('Sparse infill pattern') || value('Infill pattern');
        const summary = [stepName(step.last.label), walls && `${walls} walls`, density && `${density}${pattern ? ` ${pattern}` : ''}`]
          .filter(Boolean).join(' · ');
        const more = Math.max(0, settings.length - 2);
        entries.push(
          <section className="agent-change-summary" aria-label="Agent changes" key={step.first.seq}>
            <button type="button" aria-expanded={summaryExpanded} onClick={() => setSummaryExpanded(!summaryExpanded)}>
              <span className="settings-changes-icon" aria-hidden="true" />
              <span className="agent-change-summary-label">{summary}</span>
              <span className="agent-change-summary-more">{more > 0 ? `+${more}` : ''}{summaryExpanded ? '⌃' : '⌄'}</span>
            </button>
            {summaryExpanded && <div className="agent-change-summary-details" role="list">
              {settings.map((run) => <div className="settings-change-row change-row" role="listitem" key={run.first.seq}>
                <span className="settings-change-name">{run.last.label}</span>
                <span className="settings-change-from">{run.first.from || 'none'}</span>
                <span className="settings-change-arrow" aria-hidden="true">→</span>
                <strong>{run.last.to || 'none'}</strong>
              </div>)}
            </div>}
          </section>,
        );
        index = end;
        continue;
      }
    }
    let end = index;
    while (end < runs.length && isAgentSetting(runs[end])) end += 1;
    if (end - index > 1) {
      const group = runs.slice(index, end);
      const visible = settingsExpanded ? group : group.slice(0, 4);
      const remaining = group.length - visible.length;
      entries.push(
        <section className="settings-changes" aria-label="Agent setting changes" key={group[0].first.seq}>
          <div className="settings-changes-heading">
            <span className="settings-changes-icon" aria-hidden="true" />
            <span>{visible.length} {remaining > 0 ? `of ${group.length}` : ''} settings</span>
          </div>
          <div className="settings-changes-rows" role="list">
            {visible.map((run) => (
              <div className="settings-change-row change-row" role="listitem" key={run.first.seq}>
                <span className="settings-change-name">{run.last.label}</span>
                <span className="settings-change-from">{run.first.from || 'none'}</span>
                <span className="settings-change-arrow" aria-hidden="true">→</span>
                <strong>{run.last.to || 'none'}</strong>
              </div>
            ))}
          </div>
          {remaining > 0 && (
            <button type="button" className="settings-changes-more" onClick={() => setSettingsExpanded(true)}>
              See the other {remaining} →
            </button>
          )}
          {settingsExpanded && group.length > 4 && (
            <button type="button" className="settings-changes-more" onClick={() => setSettingsExpanded(false)}>Show fewer</button>
          )}
        </section>,
      );
      index = end;
      continue;
    }
    const run = runs[index];
    entries.push(
      <div key={run.first.seq} className="change-row" role="listitem" data-testid={`change-${run.first.seq}`}>
        <span className="change-icon" aria-hidden="true">✎</span>
        <div className="change-text">
          <span className="change-title">{title(run)}</span>
          <span className="change-meta">{meta(run)}</span>
        </div>
        {/* An inner checkpoint cannot represent the entire merged row. */}
        {onRevert && points.has(run.last.seq) && (
          <span className="change-revert-action">
            <button type="button" className="change-revert-button" aria-label="Revert to here"
              aria-expanded={open === points.get(run.last.seq)}
              onClick={(event) => {
                anchor.current = event.currentTarget;
                setOpen(open === points.get(run.last.seq) ? null : points.get(run.last.seq)!);
              }}>
              <span className="change-revert-icon" aria-hidden="true" />
            </button>
            <span className="change-revert-tooltip" role="tooltip">Revert to here</span>
          </span>
        )}
      </div>,
    );
    index += 1;
  }

  return (
    <div className="change-rows" role="list" aria-label="Changes">
      {entries}
      {open && createPortal(
        <div ref={popover} className="change-revert-popover" role="dialog" aria-label="Revert to here?"
          style={{ top: position.top, left: position.left }}>
          <strong>Revert to here?</strong>
          <p>Restore the model and project settings from this saved point. Your current model is saved in Version history first. Conversation, exported files, completed prints, and printer activity stay as they are.</p>
          <div className="change-revert-buttons">
"}

{"i":3,"result":"// Tool calls that share a plan id, rendered as the one card the person
// decides. The native coordinator approves or rejects every waiting member on
// one decision and runs them in order; the card sends that decision once, for
// the first member still waiting.

import { ActionClassName, ToolActivityInfo, ToolStateName } from '../bridge/protocol';

interface Props {
  members: ToolActivityInfo[];
  headline?: string;
  // The in-app agent's turn is still running and may add members; the
  // decision waits for the whole plan.
  stillProposing?: boolean;
  onDecision: (actionId: string, decision: 'approve' | 'reject') => void;
  onCancel: (actionId: string) => void;
}

const classRank: Record<ActionClassName, number> = { read_only: 0, mutation: 1, destructive: 2 };

const memberLabels: Record<ToolStateName, string> = {
  pending: 'Waiting',
  approved: 'Queued',
  running: 'Running…',
  succeeded: 'Done',
  failed: 'Failed',
  cancelled: 'Cancelled',
  rejected: 'Rejected',
};

function groupState(members: ToolActivityInfo[]): ToolStateName {
  const states = members.map((member) => member.state);
  if (states.includes('pending')) return 'pending';
  if (states.includes('running') || states.includes('approved')) return 'running';
  if (states.includes('failed')) return 'failed';
  if (states.every((state) => state === 'succeeded')) return 'succeeded';
  return states.includes('rejected') ? 'rejected' : 'cancelled';
}

// The plan headline from the latest plan_set, when there is one.
export function planHeadline(activities: ToolActivityInfo[]): string | undefined {
  for (let index = activities.length - 1; index >= 0; --index) {
    const activity = activities[index];
    if (activity.tool === 'plan_set' && activity.state === 'succeeded' && typeof activity.arguments.headline === 'string')
      return activity.arguments.headline;
  }
  return undefined;
}

// A plan is its source, scope and id together, as the native coordinator
// groups it: two clients or chats choosing the same id never share a card.
export function planKey(activity: ToolActivityInfo): string | undefined {
  if (!activity.planId) return undefined;
  return [activity.source ?? 'agent', activity.planScope ?? '', activity.planId].join('\u001f');
}

// Each plan's members in proposal order, keyed by planKey.
export function planMembers(activities: ToolActivityInfo[]): Map<string, ToolActivityInfo[]> {
  const plans = new Map<string, ToolActivityInfo[]>();
  for (const activity of activities) {
    const key = planKey(activity);
    if (!key) continue;
    plans.set(key, [...(plans.get(key) ?? []), activity]);
  }
  return plans;
}

export function PlanActivityCard({ members, headline, stillProposing, onDecision, onCancel }: Props) {
  const state = groupState(members);
  const highest = members.reduce<ActionClassName>(
    (top, member) => (classRank[member.actionClass] > classRank[top] ? member.actionClass : top), 'read_only');
  const destructive = members.find((member) => member.actionClass === 'destructive');
  const waiting = members.find((member) => member.state === 'pending');
  const active = members.filter((member) => member.state === 'approved' || member.state === 'running');
  const done = members.filter((member) => member.state === 'succeeded').length;

  return (
    <div className={`tool-card plan-card state-${state}`} data-testid={`plan-${members[0].planId}`}>
      <div className="tool-title">{headline ?? `A plan of ${members.length} changes`}</div>
      <div className="tool-meta">
        {members.length} {members.length === 1 ? 'change' : 'changes'} · {highest === 'destructive' ? 'destructive' : 'changes the project'}
        {destructive && ` — “${destructive.title}” cannot be undone in JusPrin`}
      </div>
      <ol className="plan-members">
        {members.map((member) => (
          <li key={member.actionId} className={`plan-member state-${member.state}`}>
            <span className="plan-member-title">{member.title}</span>
            <span className="tool-state">
              {member.actionClass === 'destructive' ? 'Destructive · ' : ''}
              {memberLabels[member.state]}
            </span>
            {member.state === 'failed' && member.error && <div className="tool-error">{member.error.message}</div>}
          </li>
        ))}
      </ol>

      {waiting && (
        <div className="tool-actions">
          <span className="tool-state">{stillProposing ? 'The Agent is still adding to this plan' : 'Waiting for your approval'}</span>
          <button className="primary" disabled={stillProposing} onClick={() => onDecision(waiting.actionId, 'approve')}>
            Approve all
          </button>
          <button disabled={stillProposing} onClick={() => onDecision(waiting.actionId, 'reject')}>Reject all</button>
        </div>
      )}

      {!waiting && active.length > 0 && (
        <div className="tool-actions">
          <progress aria-label="Plan progress" max={members.length} value={done} />
          <span className="tool-state">{done} of {members.length}</span>
          <button onClick={() => active.forEach((member) => onCancel(member.actionId))}>Cancel</button>
        </div>
      )}

      {state === 'succeeded' && <div className="tool-state done">Done</div>}
      {state === 'rejected' && <div className="tool-state">Rejected — nothing was changed</div>}
    </div>
  );
}
"}

