}

interface HeaderProps {
  title: string;
  busy: boolean;
  onBack: () => void;
  onCreate: () => void;
  onRename: (title: string) => void;
  onDelete: () => void;
  onCollapse: () => void;
}

export function ChatHeader({ title, busy, onBack, onCreate, onRename, onDelete, onCollapse }: HeaderProps) {
  const [editing, setEditing] = useState<'rename' | 'delete' | null>(null);
  const [name, setName] = useState(title);
  const menuButton = useRef<HTMLButtonElement>(null);
  const renameInput = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editing === 'rename') renameInput.current?.select();
  }, [editing]);

  const closeDialog = () => { setEditing(null); menuButton.current?.focus(); };
  const validName = name.trim().length > 0 && Array.from(name.trim()).length <= 120;

  return <>
    <header className="chat-header">
      <button className="chat-back chat-icon" aria-label="Back to chats" title="Back to chats" onClick={onBack}>
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5-8 7 8 7" /></svg>
      </button>
      <h1 title={title}>{title}</h1>
      <NewChat busy={busy} onCreate={onCreate} />
      <ActionMenu label="Chat actions" buttonRef={menuButton} items={[
        { label: 'Rename', onSelect: () => { setName(title); setEditing('rename'); } },
        { label: 'Delete', danger: true, disabled: busy, onSelect: () => setEditing('delete') },
      ]} />
      <AgentPaneToggle onCollapse={onCollapse} />
    </header>
    {editing && <Dialog title={editing === 'rename' ? 'Rename chat' : 'Delete chat?'} onClose={closeDialog}
      destructive={editing === 'delete'}>
      {editing === 'rename' ? <form onSubmit={(event) => {
        event.preventDefault();
        if (validName) { onRename(name.trim()); closeDialog(); }
      }}>
        <label htmlFor="chat-title-input">Chat title</label>
        <input id="chat-title-input" ref={renameInput} value={name} onChange={(event) => setName(event.target.value)} />
        {!validName && <p role="alert">Enter a title of 1–120 characters.</p>}
        <div className="chat-dialog-buttons"><button type="button" onClick={closeDialog}>Cancel</button>
          <button className="primary" disabled={!validName} type="submit">Save</button></div>
      </form> : <>
        <p>Delete “{title}” and its messages? Your model, builds, and print history will stay. This cannot be undone.</p>
        <div className="chat-dialog-buttons"><button onClick={closeDialog}>Cancel</button>
          <button className="danger" disabled={busy} onClick={() => { onDelete(); closeDialog(); }}>Delete</button></div>
      </>}
    </Dialog>}
  </>;
}

export function chatTimestamp(timestamp: string, now = new Date()): string {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '';
  const day = (value: Date) => Date.UTC(value.getFullYear(), value.getMonth(), value.getDate());
  const days = Math.max(0, Math.round((day(now) - day(date)) / 86400000));
  if (days === 0) return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  if (days === 1) return 'Yesterday';
  if (days < 7) return `${days} days ago`;
  if (days < 14) return 'Last week';
  if (days < 28) return `${Math.floor(days / 7)} weeks ago`;
  return date.toLocaleDateString([], { month: 'short', day: 'numeric', ...(date.getFullYear() !== now.getFullYear() ? { year: 'numeric' } : {}) });
}

export function ChatList({ conversations, activeId, busy, agentUnavailable, onSwitch, onCreate, onConfigure, onCollapse }: {
  conversations: ConversationInfo[];
  activeId: string;
  busy: boolean;
  agentUnavailable: boolean;
  onSwitch: (id: string) => void;
  onCreate: () => void;
  onConfigure: () => void;
  onCollapse: () => void;
}) {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => clearInterval(timer); }, []);
  return <section className="chat-list-pane" aria-label="Project chats">
    <header className="chat-list-header"><h1>Chats</h1><NewChat busy={busy} onCreate={onCreate} />
      <AgentPaneToggle onCollapse={onCollapse} /></header>
    <div className="chat-list-scroll">
      {conversations.length === 0 && <p className="chat-list-empty">No chats yet. Start a new chat about this project.</p>}
      {conversations.map((chat) => {
        const preview = (chat.preview || 'No messages yet').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/[*#`_]/g, '').replace(/\s+/g, ' ');
        return <button key={chat.id} className={`chat-list-row${chat.id === activeId ? ' selected' : ''}`}
          aria-current={chat.id === activeId ? 'true' : undefined} aria-label={`Open chat: ${chat.title}`}
          disabled={busy && chat.id !== activeId} onClick={() => onSwitch(chat.id)}>
          <span className="chat-list-row-top"><ChatIcon /><strong title={chat.title}>{chat.title}</strong>
            <time dateTime={chat.updatedAt || chat.createdAt} title={chat.updatedAt || chat.createdAt}>{chatTimestamp(chat.updatedAt || chat.createdAt, now)}</time></span>
          <span className="chat-list-preview">{preview}</span>
        </button>;
      })}
    </div>
    <footer className="chat-list-footer">
      <button className="configure-agent" onClick={onConfigure} disabled={busy}>
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 3-.5 3-2 1-2.5-1-2 3 2 2v2l-2 2 2 3 2.5-1 2 1 .5 3h4l.5-3 2-1 2.5 1 2-3-2-2v-2l2-2-2-3-2.5 1-2-1L13 3Z" /><circle cx="11" cy="12" r="3" /></svg>
        <span>
          <strong>{agentUnavailable ? 'Set up the agent' : 'Configure Agent'}</strong>
          <small>{agentUnavailable ? 'Connect an Agent to continue this conversation' : 'Adjust defaults, models, and slice preferences'}</small>
        </span>
      </button>
    </footer>
  </section>;
}
"}
{"i":1,"result":"// The setup card: what the agent heard, what it will cost, and how far the
// project has drifted from its preset. It sits above the thread and every
// pixel it takes comes out of the conversation, so it rests at three lines and
// grows only for something you have not seen.
//
// Each row has its own presence rule, and every fallback ends in omitting the
// row -- never a placeholder, a zero, or a guess. Missing data therefore makes
// the card shorter, never broken. When every optional row is gone the kicker
// goes too: a heading over one line is furniture, and what is left is a label
// rather than a card.

import { PresetDeltaInfo, WorkspaceContext } from '../bridge/protocol';

export interface SetupCardProps {
  context: WorkspaceContext | null;
  expanded: boolean;
  onToggle: () => void;
  // The agent is mid-thought. The card greys but does not empty: what it shows
  // is still exactly what Slice would produce this second, so the invariant
  // holds even while the answer is being written.
  working?: boolean;
}

// "~3h 50" over an hour, "~50 min" under it. Seconds are never shown: the
// number is an estimate and false precision reads as a promise.
export function formatPrintTime(seconds: number): string {
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `~${minutes} min`;
  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}`;
}

export function formatGrams(grams: number): string {
  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
}

// OrcaSlicer has no currency concept -- filament_cost's unit is literally
// "money/kg" -- so the host reads the ISO code from the machine's regional
// settings and the page formats it the way that viewer's locale writes money:
// symbol placement, grouping, and the right number of decimals (yen has none).
// Without a code there is nothing to denominate the number in, so it carries
// the word "cost" the way the slicer's own G-code legend does.
export function formatCost(cost: number, currency: string): string {
  if (currency) {
    try {
      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
    } catch {
      // An unknown code is not worth losing the number over.
    }
  }
  return `cost ${cost.toFixed(2)}`;
}

interface CardModel {
  kicker: boolean;
  // 2c: the figure a running slice is about to replace, struck through, with
  // "re-slicing..." beside it on the same line. The number stays because the
  // reader is watching for the difference, and a blank kills the comparison.
  struckEstimate: string;
  inlineNote: string;
  // 2d: the estimate reads plainly -- it is the last honest figure, not a
  // discarded one -- and a plain-language row underneath says what took it.
  reason: string;
  outOfDate: boolean;
  // 2e: how many of the deltas you made by hand. Shown only when the agent
  // made some of the others -- with nothing to stand apart from, "+7 yours"
  // over "7 changes from preset" says the same thing twice.
  yours: number;
  title: string;
  identity: string;
  summary: string;
  facts: string[];
  deltas: PresetDeltaInfo[];
  deltaLabel: string;
  preset: string;
  material: string;
}

// Everything the card decides about itself, derived once so the resting card
// and the expansion cannot disagree about what is present.
export function cardModel(context: WorkspaceContext): CardModel {
  const active = context.plates.find((plate) => plate.active) ?? null;
  const estimate = active?.estimate ?? null;
  const deltas = context.presetDeltas;
  const title = context.setupIntent.trim();
  // The deltas are measured against the process preset, so that is the name
  // the card shows -- never the printer, which already lives in the top bar.
  // A printer with no process preset has no process settings to drift from
  // either, so there is nothing here to name and the card says nothing.
  const preset = context.printer.process.trim();
  // The material the plan is written against, so a filament change shows up here as
  // well as on the chip. The "@printer" qualifier is dropped as the chip drops
  // it: it disambiguates presets in a settings list and says nothing here.
  const material = context.printer.filament.split('@')[0].trim();

  const status = active?.estimateStatus ?? 'current';
  const changeWord = deltas.length === 1 ? 'change' : 'changes';
  const deltaLabel = deltas.length === 0 ? '' :
    status === 'recomputing' ? `${deltas.length} ${changeWord}`
                             : `${deltas.length} ${changeWord} from preset`;

  // A card earns its heading by having something to say. The preset name on
  // its own does not count: nothing was delegated and nothing has moved, so
  // what is left is a label and the caller renders it as one.
  const substantive = Boolean(title) || estimate !== null || deltaLabel !== '';

  const identity = !title && preset && substantive ? preset : '';
  const wall = deltas.find((delta) => delta.label === 'Wall loops')?.value;
  const density = deltas.find((delta) => delta.label === 'Sparse infill density')?.value;
  const pattern = deltas.find((delta) => delta.label === 'Sparse infill pattern')?.value;
  const mainSettings = [wall && `${wall} walls`, density && `${density} ${pattern || 'infill'}`].filter(Boolean);
  const summary = mainSettings.length > 0 ? mainSettings.join(' · ')
    : deltas.slice(0, 2).map((delta) => `${delta.label} ${delta.value}`).join(' · ');

  const recomputing = estimate !== null && status === 'recomputing';
  const outOfDate = estimate !== null && status === 'stale';

  const hand_edited = deltas.filter((delta) => delta.origin === 'user').length;
  const yours = hand_edited > 0 && hand_edited < deltas.length ? hand_edited : 0;

  const facts: string[] = [];
  // Stale keeps its figure on the facts line, unstruck: it is the last number
  // the card could defend, not one already superseded by a better answer.
  if (estimate && !recomputing) {
    facts.push(formatPrintTime(estimate.printTimeSeconds));
    facts.push(formatGrams(estimate.materialGrams));
    // A priced job so small it rounds to nothing reads exactly like the
    // unpriced case, so it takes the same exit: no clause rather than 0.00.
    if (estimate.materialCost !== null && estimate.materialCost >= 0.005)
      facts.push(formatCost(estimate.materialCost, context.currency));
  }

  const struckEstimate = recomputing && estimate
    ? [formatPrintTime(estimate.printTimeSeconds), formatGrams(estimate.materialGrams)].join(' · ')
    : '';
  const inlineNote = recomputing ? 're-slicing…' : '';
  // Names the action when it is known and asks for the re-slice either way,
  // rather than attributing the loss to something the reader did not do.
  const reason = outOfDate ? (active?.invalidatedBy ?? '') : '';
  // "Not sliced yet" is a claim about the plate, not about whether we happen
  // to hold a number: a sliced plate that yielded no usable estimate must not
  // be described as unsliced. With no plate at all there is nothing to say.
  if (substantive && !estimate && active !== null && !active.sliced) facts.push('not sliced yet');

  return { kicker: substantive, title, identity, summary, facts, deltas, deltaLabel, preset, material,
           struckEstimate, inlineNote, reason, outOfDate, yours };
}

function DeltaList({ deltas }: { deltas: PresetDeltaInfo[] }) {
  return (
    <dl className="current-setup-deltas">
      {deltas.map((delta) => (
        <div key={delta.key}>
          <dt title={delta.key}>{delta.label || delta.key}</dt>
          <dd>
            <span className="was">{delta.preset}</span>
            <span aria-hidden="true"> → </span>
            <span className="now">{delta.value}</span>
            {/* The count in the eyebrow is only worth trusting if opening the
                card says which ones it meant. Separated the way the facts line
                separates its clauses: without the dot it reads as part of the
                value, which is the one thing this row must not blur. */}
            {delta.origin === 'user' && <span className="yours"> · yours</span>}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export function SetupCard({ context, expanded, onToggle, working }: SetupCardProps) {
  if (!context) return null;
  const model = cardModel(context);

  // Noth…1446 tokens truncated…return 'JusPrin closed this without answering it.';
  if (message.answer === 'no') return 'JusPrin answered No to this question.';
  if (message.answer === 'cancel') return 'JusPrin chose Cancel for this question.';
  return undefined;
}

function fileName(path: string): string {
  return path.split(/[\\/]/).pop() ?? path;
}

export function FileNotesCard({ report, onSetUpAgent }: Props) {
  const files = report.loads.flatMap((load) => load.files).map(fileName);
  return (
    <article className="history-card file-notes-card" aria-label="Notes about this file">
      <h3 className="file-notes-title">Notes about this file</h3>
      {files.length > 0 && <p className="file-notes-files">{files.join(', ')}</p>}
      <ul className="file-notes-list">
        {report.messages.items.map((message, index) => {
          const note = answerNote(message);
          return (
            <li key={index}>
              {message.title && <span className="file-notes-heading">{heading(message.title)}</span>}
              {message.text && <span className="file-notes-text">{message.text}</span>}
              {note && <span className="file-notes-answer">{note}</span>}
            </li>
          );
        })}
      </ul>
      {report.messages.truncated && <p className="file-notes-more">OrcaSlicer said more than fits here.</p>}
      <p className="file-notes-help">If you'd like help with these, set up the Agent: it can explain them and fix what needs fixing.</p>
      {onSetUpAgent && (
        <button type="button" className="primary" onClick={onSetUpAgent}>
          Set up the Agent
        </button>
      )}
    </article>
  );
}
