/* The provider switch is one control, so it carries the compact action
   radius rather than a container's. */
.setup-tabs {
  display: flex;
  width: 100%;
  border-radius: var(--radius-compact);
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.setup-tab {
  flex: 1;
  padding: var(--button-secondary-padding);
  border: none;
  border-radius: 0;
  background: var(--surface-canvas);
  color: var(--text-primary);
  cursor: pointer;
}

.setup-tab:hover:enabled,
.setup-tab:active:enabled {
  border: none;
}

.setup-tab.selected {
  background: var(--action-primary);
  color: var(--action-primary-text);
}

.setup-tab.selected:hover:enabled {
  background: var(--action-primary);
}

.setup-tab:disabled {
  background: var(--action-disabled);
  color: var(--action-disabled-text);
  cursor: default;
}

