.tool-card .tool-actions > button:not(.primary) { border-color: var(--border-subtle); }

.tool-card .tool-state {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.tool-card .tool-state.done {
  color: var(--status-success);
}

.tool-card .tool-error {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 4px;
  font: var(--font-body-small);
  color: var(--status-danger);
}

.tool-card progress {
  display: block;
  width: 100%;
  height: var(--printer-card-progress-height);
  margin-top: 8px;
  accent-color: var(--action-primary);
}

.tool-status-icon {
  display: inline-block;
  flex: 0 0 auto;
  width: var(--button-icon-icon-size);
  height: var(--button-icon-icon-size);
  background: currentColor;
  -webkit-mask: url('@resources/jusprin/ui/icons/ellipsis.svg') center / contain no-repeat;
  mask: url('@resources/jusprin/ui/icons/ellipsis.svg') center / contain no-repeat;
}
.tool-status-icon.running { -webkit-mask-image: url('@resources/jusprin/ui/icons/rotate-cw.svg'); mask-image: url('@resources/jusprin/ui/icons/rotate-cw.svg'); }
.tool-status-icon.done { -webkit-mask-image: url('@resources/jusprin/ui/icons/check.svg'); mask-image: url('@resources/jusprin/ui/icons/check.svg'); }
.tool-status-icon.failed { -webkit-mask-image: url('@resources/jusprin/ui/icons/circle-alert.svg'); mask-image: url('@resources/jusprin/ui/icons/circle-alert.svg'); }
.tool-status-icon.cancelled { -webkit-mask-image: url('@resources/jusprin/ui/icons/circle-minus.svg'); mask-image: url('@resources/jusprin/ui/icons/circle-minus.svg'); }
.tool-cancel { margin-top: 8px; padding: 0; border: none; color: var(--action-primary); font: var(--font-label-bold); text-decoration: underline; }
.tool-cancel:hover:enabled { border-color: transparent; color: var(--action-primary-hover); text-decoration: underline; }

.tool-card .plan-members {
  margin: 4px 0 0;
  padding-left: 16px;
}

.tool-card .plan-member {
  font: var(--font-label);
}

