+++ b/src/slic3r/GUI/JusPrin/Shell/HeaderControls.cpp
@@ -1,18 +1,96 @@
 #include "HeaderControls.hpp"
+#include "libslic3r/Utils.hpp"
+#include "nanosvg/nanosvg.h"
+#include "nanosvg/nanosvgrast.h"
+#include <boost/algorithm/string/replace.hpp>
